extends SceneTree

const GOLDEN := -7046029254386353131
const C1 := -4658895280553007687
const C2 := -7723592293110705685

static func lsr(x: int, n: int) -> int:
	return (x >> n) & ((1 << (64 - n)) - 1)
static func mix64(z: int) -> int:
	z = (z ^ lsr(z, 30)) * C1
	z = (z ^ lsr(z, 27)) * C2
	return z ^ lsr(z, 31)
static func ihash(seed_: int, k1: int, k2: int, k3: int, salt: int) -> int:
	return lsr(mix64(mix64(k1 ^ seed_) ^ mix64(k2 ^ salt) ^ (k3 * GOLDEN)), 1)

# ---- reference encoder ----
var buf := PackedByteArray()
func w8(v: int) -> void:
	buf.append(v)
func w64(v: int) -> void:
	var o := buf.size()
	buf.resize(o + 8)
	buf.encode_s64(o, v)
func wfloat(f: float) -> void:
	var o := buf.size()
	buf.resize(o + 8)
	if f != f:
		buf.encode_s64(o, 0x7FF8000000000000)
	elif f == 0.0:
		buf.encode_s64(o, 0)
	else:
		buf.encode_double(o, f)
func wbytes(b: PackedByteArray) -> void:
	buf.append_array(b)

func enc(v: Variant) -> void:
	match typeof(v):
		TYPE_NIL: w8(0x00)
		TYPE_BOOL:
			w8(0x01); w8(1 if v else 0)
		TYPE_INT:
			w8(0x02); w64(v)
		TYPE_FLOAT:
			w8(0x03); wfloat(v)
		TYPE_STRING, TYPE_STRING_NAME:
			var u := String(v).to_utf8_buffer()
			w8(0x04); w64(u.size()); wbytes(u)
		TYPE_VECTOR2:
			w8(0x05); wfloat(v.x); wfloat(v.y)
		TYPE_VECTOR2I:
			w8(0x06); w64(v.x); w64(v.y)
		TYPE_ARRAY:
			w8(0x07); w64(v.size())
			for e in v: enc(e)
		TYPE_DICTIONARY:
			w8(0x08); w64(v.size())
			var ks: Array = v.keys()
			if ks.size() > 0 and typeof(ks[0]) == TYPE_INT:
				ks.sort()
			else:
				var ss: Array = []
				for k in ks: ss.append(String(k))
				ss.sort()
				# map back
				var back: Array = []
				for s in ss:
					back.append(s if v.has(s) else StringName(s))
				ks = back
			for k in ks:
				enc(k); enc(v[k])
		TYPE_PACKED_BYTE_ARRAY:
			w8(0x09); w8(1); w64(v.size()); wbytes(v)
		TYPE_PACKED_INT32_ARRAY:
			w8(0x09); w8(2); w64(v.size()); wbytes(v.to_byte_array())
		TYPE_PACKED_INT64_ARRAY:
			w8(0x09); w8(3); w64(v.size()); wbytes(v.to_byte_array())
		_:
			push_error("unsupported type %d" % typeof(v))

func ENC(v: Variant) -> PackedByteArray:
	buf = PackedByteArray()
	enc(v)
	return buf.duplicate()

func H64(b: PackedByteArray) -> int:
	var c := HashingContext.new()
	c.start(HashingContext.HASH_SHA256)
	c.update(b)
	return c.finish().decode_s64(0)

func hx(x: int) -> String:
	var b := PackedByteArray(); b.resize(8); b.encode_s64(0, x)
	var r := PackedByteArray()
	for i in range(7, -1, -1): r.append(b[i])
	return "0x" + r.hex_encode().to_upper()

func show(label: String, v: Variant) -> void:
	var b := ENC(v)
	print(label, " [", b.size(), "] ", b.hex_encode(), " H64=", hx(H64(b)))

func _init() -> void:
	show("INT 1", 1)
	show("FLOAT 1.0", 1.0)
	show("[[1],[2,3]]", [[1], [2, 3]])
	show("[[1,2],[3]]", [[1, 2], [3]])
	show("&a", &"a")
	show("a", "a")
	show("{b:1,a:2}", {"b": 1, "a": 2})
	show("{a:2,b:1}", {"a": 2, "b": 1})
	show("{10:1,-5:2,3:3}", {10: 1, -5: 2, 3: 3})
	show("PackedInt32 [1,-2]", PackedInt32Array([1, -2]))
	show("Vector2(-0.0, 1.0)", Vector2(-0.0, 1.0))
	show("Vector2i(-1, 2)", Vector2i(-1, 2))
	show("nil", null)
	show("true", true)
	# state_hash framing example
	var T := 5000
	var ws := 0x5EED000000002026
	var blocks := [
		["a.state", 1, {"x": 1}],
		["b.state", 2, [1, 2]],
	]
	var fb := PackedByteArray()
	fb.resize(16)
	fb.encode_s64(0, T)
	fb.encode_s64(8, ws)
	for bl in blocks:
		var payload := ENC(bl[2])
		var idb := String(bl[0]).to_utf8_buffer()
		var rec := PackedByteArray()
		rec.resize(8); rec.encode_s64(0, idb.size()); rec.append_array(idb)
		var t8 := PackedByteArray(); t8.resize(8)
		t8.encode_s64(0, bl[1]); rec.append_array(t8)
		t8.encode_s64(0, payload.size()); rec.append_array(t8)
		t8.encode_s64(0, H64(payload)); rec.append_array(t8)
		print("block ", bl[0], " enc=", payload.hex_encode(), " block_hash=", hx(H64(payload)))
		fb.append_array(rec)
	print("state_hash input [", fb.size(), "] state_hash=", hx(H64(fb)))
	# ihash vectors
	var hs := 0x4845
	print("ihash(seed=0x4845, 1,0,0,salt=1)=", hx(ihash(hs, 1, 0, 0, 1)), " dec ", ihash(hs, 1, 0, 0, 1))
	print("ihash(0x4845, 17,3,5,2)=", hx(ihash(hs, 17, 3, 5, 2)))
	print("ihash(0x4845, -1,-1,-1,5)=", hx(ihash(hs, -1, -1, -1, 5)))
	print("ihash(0,0,0,0,0)=", hx(ihash(0, 0, 0, 0, 0)))
	print("ihash(0x4845, 1,0,0,1) >=0 ", ihash(hs, 1, 0, 0, 1) >= 0)
	# rng_int integer-exact vs float
	var mism := 0
	var k := mix64(0x1234567)
	for i in 200000:
		var r := mix64(i * 7919 + k)
		var top := lsr(r, 11)
		var span := 1201
		var f := 600 + int(floor(float(top) / 9007199254740992.0 * float(span)))
		# exact: floor(top*span / 2^53) via splitting top = hi*2^21 + lo
		var hi := top >> 21
		var lo := top & 0x1FFFFF
		var ex := ((hi * span) + ((lo * span) >> 21)) >> 32
		ex += 600
		if ex != f: mism += 1
	print("rng_int float vs exact mismatches over 2e5 draws (span 1201): ", mism)
	mism = 0
	for i in 200000:
		var r := mix64(i * 104729 + k)
		var top := lsr(r, 11)
		var span := 4294967296
		var f := int(floor(float(top) / 9007199254740992.0 * float(span)))
		var hi := top >> 21
		var lo := top & 0x1FFFFF
		var ex := ((hi * span) + ((lo * span) >> 21)) >> 32
		if ex != f: mism += 1
	print("rng_int float vs exact mismatches over 2e5 draws (span 2^32; exact uses hi*span which can overflow if hi>=2^31): ", mism)
	quit()
EOF
